def solve():
    t = int(input())

    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))

        # Key insight: The operation always decreases the prefix of length 2^m
        # This means elements at positions with higher indices cannot be made smaller
        # than elements at positions with lower indices

        # Check if the operation is possible by ensuring each element is not greater
        # than any element that comes after it in positions that can't be affected
        # differently by our operations

        can_sort = True
        for i in range(n):
            for j in range(i+1, n):
                # Find highest power of 2 that covers i but not j
                if i < j:
                    k = 0
                    while (1 << k) <= i:
                        k += 1

                    # Ensure the first element can be made less than or equal to the second
                    # after applying operations
                    if arr[i] > arr[j]:
                        highest_power = 0
                        while (1 << highest_power) <= n:
                            highest_power += 1

                        # Check if there's a way to make arr[i] <= arr[j]
