import sys

def solve():
    t = int(input())
    results = []

    def is_good_string(s):
        return all(s[i] != s[i+1] for i in range(len(s)-1))

    def can_make_good(s, t):
        # If s is already good, no need for operations
        if is_good_string(s):
            return True

        # Check if t is good - if not, can't help make s good
        if not is_good_string(t):
            return False

        # If t has same first and last character, it can't fix consecutive same characters
        if len(t) > 1 and t[0] == t[-1]:
            return False

        # Find problematic positions in s (where s[i] == s[i+1])
        problematic = [i for i in range(len(s)-1) if s[i] == s[i+1]]

        # For each problematic position, see if t can fix it
        return any(
            (t[0] != s[i] or t[-1] != s[i+1])
            for i in problematic
        )

    for _ in range(t):
        n, m = map(int, input().split())
        s = input().strip()
        t = input().strip()

        if can_make_good(s, t):
            results.append("YES")
        else:
            results.append("NO")

    return "\n".join(results)
