import sys

def solve():
    t = int(input())
    results = []

    def is_good(s):
        if len(s) == 1:
            return True

        return all(s[i] != s[i+1] for i in range(len(s)-1))

    def can_make_good(s, t):
        # Check if s is already good
        if is_good(s):
            return "Yes"

        # Check if t is good and has different characters at both ends
        if not is_good(t):
            return "No"

        # Check if inserting t can help eliminate adjacent same characters
        # Find all pairs of same characters
        bad_pairs = [i for i in range(len(s)-1) if s[i] == s[i+1]]

        # If t starts and ends with different characters, it can break bad pairs
        if len(t) >= 2 and t[0] != t[-1]:
            return "Yes"

        # If t is just a single character, it can't help
        if len(t) == 1:
            return "No"

        # Special case: check if t can be inserted between any bad pair to make it good
        def can_insert_and_fix():
            for i in bad_pairs:
                # Try inserting t between s[i] and s[i+1]
                if s[i] != t[0] and s[i+1] != t[-1]:
                    return True
            return False

        if can_insert_and_fix():
            return "Yes"

        return "No"

    for _ in range(t):
        n, m = map(int, input().split())
        s = input().strip()
        t = input().strip()
        results.append(can_make_good(s, t))

    return "\n".join(results)
