import sys

def solve():
    t = int(input())
    results = []

    def is_good(s):
        if len(s) <= 1:
            return True
        return all(s[i] != s[i+1] for i in range(len(s)-1))

    def contains_consecutive(s):
        return any(s[i] == s[i+1] for i in range(len(s)-1))

    def can_fix(s, t):
        # If s is already good, we don't need to do anything
        if is_good(s):
            return True

        # If t contains consecutive same characters, it can't help make s good
        if contains_consecutive(t):
            return False

        # If first and last characters of t are the same, t can't be used to break consecutive characters
        if t[0] == t[-1]:
            return False

        # If all characters in s are the same (e.g., "111"), we need to check if insertion of t can help
        if all(c == s[0] for c in s):
            # If t starts and ends with the same character as s, we can't make s good
            if t[0] == s[0] and t[-1] == s[0]:
                return False

        # Check if t can be used to break consecutive same characters in s
        i = 0
        while i < len(s) - 1:
            if s[i] == s[i+1]:  # Found consecutive characters
                # Check if inserting t here helps
                if (t[0] != s[i] or t[-1] != s[i+1]):
                    return True
            i += 1

        # If we can't break consecutive characters with t, it's not possible
        return False

    i = 0
    while i < t:
        n, m = map(int, input().split())
        s = input().strip()
        t = input().strip()

