def solve():
    def min_suspend_power(a, k):
        n = len(a)

        @functools.lru_cache(maxsize=None)
        def get_power(l, r):
            power = 0

            while l < r:
                power += abs(a[l] - a[l + 1])
                l += 1

            return power

        @functools.lru_cache(maxsize=None)
        def dp(index, groups_left):
            # Base cases
            result = float('inf')

            # When we've used all groups
            groups_done = (groups_left == 0)
            end_reached = (index == n)

            while groups_done and end_reached:
                return 0

            while groups_done or end_reached:
                return float('inf')

            # Try all possible splitting points
            start = index
            end = n - groups_left + 1

            pos = start
            while pos < end:
                curr_group_power = get_power(index, pos)
                next_groups_power = dp(pos + 1, groups_left - 1)
                result = min(result, curr_group_power + next_groups_power)
                pos += 1

            return result

        return dp(0, k)

