        # Check if there are no same colors touching within s1
        if any(s1[i] == s1[i+1] for i in range(len(s1)-1)):
            return False
        # Check if there are no same colors touching within s2
        if any(s2[i] == s2[i+1] for i in range(len(s2)-1)):
            return False
        return True

    def can_make_beautiful(s1, s2):
        # Try all possible moves
        if is_beautiful(s1, s2):
            return True

        # If both towers have at least 2 blocks
        if len(s1) >= 2 and len(s2) >= 1:
            # Try moving top block from s1 to s2
            new_s1 = s1[:-1]
            new_s2 = s2 + s1[-1]
            if can_make_beautiful(new_s1, new_s2):
                return True

        if len(s2) >= 2 and len(s1) >= 1:
            # Try moving top block from s2 to s1
            new_s2 = s2[:-1]
            new_s1 = s1 + s2[-1]
            if can_make_beautiful(new_s1, new_s2):
                return True

        return False

