        # If total is even, both towers will have same parity (both odd or both even)
        total = len(combined)

        # For towers to be alternating, we need to check if the blocks can be arranged correctly
        # If total is even, then R and B counts must be equal
        # If total is odd, then one color must have one more block than the other
        if total % 2 == 0:
            return r_count == b_count
        else:
            return abs(r_count - b_count) == 1

