    def factorial(n):
        return math.factorial(n)

    def is_multiple(a, b):
        return a % b == 0

    def process_test_case(k):
        # Check if x = k - 1 satisfies the condition
        if k > 2:
            x = k - 1
            if is_multiple(factorial(x) + factorial(x - 1), k):
                return x

        # Check for prime k
        if k > 2 and all(k % i != 0 for i in range(2, int(math.sqrt(k)) + 1)):
            return k - 1

        # For k that is a power of 2
        if (k & (k - 1)) == 0:  # Check if k is a power of 2
            return k - 1

        # For general cases
