        # Note that x! + (x-1)! = (x-1)! * (x+1)
        # So we need to find largest x such that k divides (x-1)! * (x+1)

        # For composite k
        if k == 4:
            return 3

        # For other cases, usually k-1 works
        x = k - 1
        if is_multiple(factorial(x) + factorial(x - 1), k):
            return x

        # If k is a prime p, and p divides (p-2)! + (p-3)!, then p-2 works
        if k > 3:
