def compare_sizes(a, b):
    # Create a function to convert size to a comparable value
    def get_size_value(size):
        # Medium is in the middle
        if size == 'M':
            return 0

        # Extract the number of X's
        x_count = size.count('X')

        # For small sizes, the more X's, the smaller
        if size.endswith('S'):
            return -1 - x_count

        # For large sizes, the more X's, the larger
        if size.endswith('L'):
            return 1 + x_count

    a_value = get_size_value(a)
    b_value = get_size_value(b)

    return '<' if a_value < b_value else '>' if a_value > b_value else '='

