        moves = [
            (r-2, c-1), (r-2, c+1),
            (r-1, c-2), (r-1, c+2),
            (r+1, c-2), (r+1, c+2),
            (r+2, c-1), (r+2, c+1)
        ]

        valid_moves = [(r_new, c_new) for r_new, c_new in moves 
                        if 1 <= r_new <= n and 1 <= c_new <= m]

        return len(valid_moves) == 0

