import sys

def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n = int(input())
        words = [input().split() for _ in range(3)]

        word_count = {}

        for person_id, person_words in enumerate(words):
            for word in person_words:
                word_count[word] = word_count.get(word, 0) | (1 << person_id)

        points = [0, 0, 0]

        for word, count_bits in word_count.items():
            ones_count = bin(count_bits).count('1')

            for person_id in range(3):
                mask = 1 << person_id
                person_has_word = (count_bits & mask) > 0

                points[person_id] += (
                    3 * (ones_count == 1 and person_has_word) or 
                    1 * (ones_count == 2 and person_has_word)
                )

        results.append(' '.join(map(str, points)))

    return '\n'.join(results)
