def min_moves(n):
    # Take the absolute value since negative distances require the same number of moves
    n = abs(n)

    # Edge cases for small values of n
    if n == 1:
        return 2  # 0 -> 3 -> 1 (2 moves)
    if n == 2 or n == 3:
        return 1  # Direct move
    if n == 4:
        return 2  # 0 -> 2 -> 4 (2 moves)
    if n == 5:
        return 3  # 0 -> 2 -> 4 -> 5 or 0 -> 3 -> 5 -> 7 -> 5 (3 moves)

    # For larger values, we can prove that:
    # - If n mod 5 = 0, then moves = n // 5 * 2
    # - If n mod 5 = 1, then moves = n // 5 * 2 + 1
    # - If n mod 5 = 2, then moves = n // 5 * 2 + 2
    # - If n mod 5 = 3, then moves = n // 5 * 2 + 1
    # - If n mod 5 = 4, then moves = n // 5 * 2 + 2

    quotient, remainder = divmod(n, 5)

    if remainder == 0:
        return quotient * 2
    elif remainder == 1 or remainder == 3:
        return quotient * 2 + 1
    else:  # remainder == 2 or remainder == 4
        return quotient * 2 + 2
