def find_minimum_varied_number(s):
    digits = []
    remaining_sum = s

    while remaining_sum > 0:
        digit = min(9, remaining_sum)
        digits.append(digit)
        remaining_sum -= digit

    digits.sort()

    return int(''.join(map(str, digits)))
