    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = input()
        b = input()

        # If a has the same length as b, check direct equality
        if n == m:
            if a == b:
                print("YES")
                continue
            else:
                print("NO")
                continue

        # We need to reduce a from length n to length m
        # Try all possible operation sequences using dynamic programming

        # dp[i][j] = can we create sequence with first j chars of b using first i chars of a
        # i is 1-indexed for a, j is 1-indexed for b
        dp = {}

        def can_make(i, j, prev_val):
            if (i, j, prev_val) in dp:
                return dp[(i, j, prev_val)]

            # Base case: if we've used all required elements of a
            if i == n - m + j:
                # Check if the current value matches b[j-1]
                result = (prev_val == int(b[j-1]))
                dp[(i, j, prev_val)] = result
                return result

            # Try operation 1: min
            if can_make(i+1, j, min(prev_val, int(a[i]))):
                dp[(i, j, prev_val)] = True
                return True

            # Try operation 2: max
            if can_make(i+1, j, max(prev_val, int(a[i]))):
                dp[(i, j, prev_val)] = True
                return True

            dp[(i, j, prev_val)] = False
            return False

        # Start from the first character of a and first character of b
        possible = False
        for i in range(n - m + 1):
            if can_make(i+1, 1, int(a[i])):
                possible = True
                continue

        if possible:
            print("YES")
        else:
            print("NO")

