            valid = True
            i, j = 0, 0

            # Check if we can transform each bit
            while i < len(a) and j < len(b) and valid:
                if j == 0:
                    # For the first position, we can choose any bit from sequence a
                    if a[i] == b[j]:
                        i += 1
                        j += 1
                    else:
                        i += 1
                else:
                    # For subsequent positions, we need to check if we can transform
                    # If current a[i] matches b[j], we can move on
                    if a[i] == b[j]:
                        i += 1
                        j += 1
                    # If current bit doesn't match, we need a different value
                    elif b[j] == '0' and a[i] == '1':
                        # We need to produce 0, can only do it using min operation
                        # Check if there's a 0 before this position in a
                        zero_found = '0' in a[:i]
                        if not zero_found:
                            valid = False
                        i += 1
                    elif b[j] == '1' and a[i] == '0':
                        # We need to produce 1, can only do it using max operation
                        # Check if there's a 1 before this position in a
                        one_found = '1' in a[:i]
                        if not one_found:
                            valid = False
                        i += 1
                    else:
                        i += 1

            # Check if we processed all of b
            valid = valid and j == len(b)

            results.append("YES" if valid else "NO")

    return '\n'.join(results)

