        # or to go down as much as possible before going right

        # Let's calculate the cost of going right first then down
        cost_right_first = 0

        # Add cost of first row (going right)
        cost_right_first += sum([(0 * m) + j for j in range(1, m + 1)])

        # Add cost of last column (going down)
        cost_right_first += sum([(i * m) + m for i in range(1, n)])

        # Let's calculate the cost of going down first then right
        cost_down_first = 0

        # Add cost of first column (going down)
        cost_down_first += sum([(i - 1) * m + 1 for i in range(1, n + 1)])

        # Add cost of last row (going right)
        cost_down_first += sum([(n - 1) * m + j for j in range(2, m + 1)])

        # Return the minimum of the two paths
        return min(cost_right_first, cost_down_first)

